function useData(mode, values) { const key = JSON.stringify(values), [data, setData] = useState(null), [error, setError] = useState(false), [loading, setLoading] = useState(true), [attempt, setAttempt] = useState(0), [loadedKey,setLoadedKey] = useState(''); useEffect(() => { let active = true; setLoading(true); setError(false); api(mode, JSON.parse(key)).then(d => { if (active) { setData(d); setLoadedKey(`${mode}:${key}`); setLoading(false); } }).catch(e => { if (active) { setError(e); setLoading(false); } }); return () => { active = false; }; }, [mode, key, attempt]); return { data, setData, error, loading: !error && (loading || loadedKey !== `${mode}:${key}`), retry: () => setAttempt(x => x + 1) }; }
function A({ href, children, className = '', ...rest }) { const local = href?.startsWith('/'); return <a href={href} className={className} {...(local ? { onClick: e => { if (!e.metaKey && !e.ctrlKey && !e.shiftKey && e.button === 0) { e.preventDefault(); navigate(href); window.scrollTo(0, 0); } } } : { target: '_blank', rel: 'noreferrer noopener' })} {...rest}>{children}{!local && <ArrowUpRight size={12} aria-hidden="true" />}</a>; }
function Marker({ kind, hollow = false, size = 10 }) { return <svg className={`marker ${kind} ${hollow ? 'hollow' : ''}`} width={size} height={size} viewBox="0 0 12 12" aria-label={checks[kind]}>{kind === 'src' ? <circle cx="6" cy="6" r="4.5" /> : kind === 'lang' ? <path d="M6 0.8 11.2 6 6 11.2.8 6Z" /> : kind === 'tone' ? <path d="m6 1 5.2 9H.8Z" /> : <rect x="1.5" y="1.5" width="9" height="9" />}</svg>; }
function Marked({ text = '', words = [], kind = 'lang', selected = false, dismissed = false }) { const ranges = words.flatMap(w => { const result = []; let start = 0, i; if (!w) return result; while ((i = text.indexOf(w, start)) !== -1) { result.push([i, i + w.length]); start = i + w.length; } return result; }).sort((a, b) => a[0] - b[0]); const merged = []; for (const r of ranges) { const last = merged.at(-1); if (last && r[0] <= last[1]) last[1] = Math.max(last[1], r[1]); else merged.push([...r]); } let cursor = 0; const parts = []; merged.forEach(([start, end]) => { parts.push(text.slice(cursor, start)); parts.push(<mark key={start} data-check={kind} className={`${selected ? 'selected-mark' : ''} ${dismissed ? 'dismissed-mark' : ''}`}>{text.slice(start, end)}</mark>); cursor = end; }); parts.push(text.slice(cursor)); return parts; }
function Quote({ version, flag, source = false }) { const [whole, setWhole] = useState(false); const text = source ? flag?.source?.passage || flag?.source_passage || '' : version?.text || ''; const words = source ? flag?.source_marks || [] : flag?.marks?.[version?.claim_id || version?.id] || []; const short = text.length > 320 && !whole; let excerpt = text; if (short) { const hit = words.length ? text.indexOf(words[0]) : 0; const start = Math.max(0, (hit < 0 ? 0 : hit) - 80); const end = Math.min(text.length, start + 310); excerpt = `${start ? '…' : ''}${text.slice(start, end)}${end < text.length ? '…' : ''}`; } return <><p className="quote" lang={source ? flag?.source?.language : version?.lang}><Marked text={excerpt} words={words} kind={flag?.check} selected dismissed={flag?.dismissed} /></p>{short && <button className="text-button" onClick={() => setWhole(true)}>Whole sentence</button>}</>; }
function Readings({ flag, versions, extra = false }) { const vs = versions || flag?.versions || {}, kind = flag?.check; let langs = order.filter(l => (extra || !['de', 'ru'].includes(l)) && (vs[l] || ['lang', 'fact'].includes(kind) && ['fi', 'sv', 'en'].includes(l))); if (kind === 'src' || kind === 'tone') langs = [flag.language]; return <div className="readings">{langs.map(lang => { const v = vs[lang]; return <div className="reading" key={lang}><div className="reading-meta"><span className="language-tag">{lang}</span><span>{names[lang]} Wikipedia</span>{v?.rev_id && <A href={revision(lang, v.rev_id)}>revision {v.rev_id}</A>}{v?.value && <strong className={flag && ['lang', 'fact', 'src'].includes(kind) ? `value ${kind}` : 'value'}>{v.value}</strong>}</div>{v ? <><Quote version={{ ...v, lang }} flag={flag} />{lang !== 'en' && v.gloss && <p className="gloss">{v.gloss}</p>}{v.source_verdict === 'Supported' ? <p className="source-status"><Check className="ok" size={14} /> Supported by its source</p> : ['Contradicted', 'Not in source'].includes(v.source_verdict) ? <p className="source-status"><CircleSlash className="src" size={14} /> Not in its source</p> : ['Source unreachable', 'Book, not checked'].includes(v.source_verdict) ? <p className="source-status muted">{v.source_verdict === 'Book, not checked' ? 'Book, not checked' : 'Its source could not be read'}</p> : null}</> : <p className="muted small">{flag?.verdict === `Missing in ${names[lang]}` ? `Not in the ${names[lang]} article.` : 'No matching passage found in this version.'}</p>}</div>; })}{kind === 'src' && flag.source && <div className="reading source-reading"><div className="reading-meta"><LinkIcon size={14} /><span>Cited source</span><A href={flag.source.archive_url || flag.source.url}>{new URL(flag.source.url).hostname.replace(/^www\./, '')}</A>{flag.source.archive_url && <span>archived copy</span>}</div><Quote source flag={flag} />{flag.source.gloss && flag.source.language !== 'en' && <p className="gloss">{flag.source.gloss}</p>}</div>}</div>; }
function Footer() { return <footer>Text from Wikipedia, CC BY-SA 4.0. Parallax is not part of the Wikimedia Foundation. It never edits Wikipedia.</footer>; }
function ErrorState({ retry, search = false }) { return <div className="error-state" role="alert"><TriangleAlert size={20} className="src" /><h2>{search ? 'The search did not run.' : 'The database did not answer.'}</h2><p>{search ? 'Your question was not saved. Try again.' : 'Nothing is shown from memory. Try again in a moment.'}</p><button className="quiet" onClick={retry}>Try again</button></div>; }
