function Ask({ loc }) { const {data:exampleData}=useData('examples',{}); const q = loc.searchParams.get('q') || '', { data, loading, error, retry } = useData('search', { q }); useEffect(() => { if (!q.trim()) { navigate('/'); requestAnimationFrame(() => document.querySelector('[aria-label="Ask in any language"]')?.focus()); } }, [q]); const best = data?.group, fs = data?.flags || [], flag = fs.find(f => ['fact', 'lang'].includes(f.check)) || fs[0], versions = best?.versions || {}; const answer = flag ? ['fact', 'lang'].includes(flag.check) ? 'The versions do not agree.' : flag.check === 'src' ? 'Wikipedia and its source do not agree.' : 'The wording needs a closer look.' : Object.keys(versions).length >= 2 ? 'Here are the closest stored passages.' : `Only the ${names[Object.keys(versions)[0]] || 'matching'} article covers this.`; return <><main className="ask-page"><div className="ask-main"><h1>{q}</h1><p className="small muted">{loading ? 'Searching…' : data ? `Closest of ${num(data.counts.claims)} claims and ${num(data.counts.sources_read)} source texts · ${num(data.queries?.[0]?.ms)} ms` : ''}</p>{error ? <ErrorState retry={retry} search /> : loading ? <Skeleton /> : best ? <><h2 className="answer-sentence">{answer}</h2><Readings flag={flag} versions={versions} extra /><div className="answer-actions"><A className="primary" href={`/a/${data.topic.qid}?${flag ? `flag=${flag.id}` : `show=all&claim=${best.id}`}`}>Open this claim in {data.topic.title}</A><button className="text-button" onClick={() => params({ sql: '1' })}>Show the SQL</button></div><section className="other-passages"><h2>Other close passages</h2>{data.hits.filter(h => !Object.values(versions).some(v => v.id === h.id || v.claim_id === h.id)).slice(0, 8).map(h => <div className="search-hit" key={h.id}><div className="reading-meta">{h.kind === 'claim' ? <span className="language-tag">{h.lang}</span> : <LinkIcon size={14} />}{h.qid ? <A href={`/a/${h.qid}?show=all`}>Wikipedia</A> : <A href={h.archive_url || h.url}>{h.section}</A>}{h.qid && <span>{h.section}</span>}<span className="hit-distance">distance {Number(h.distance).toFixed(2)}</span></div><p className="quote" lang={h.lang || 'und'}>{h.text}</p></div>)}</section></> : <div className="no-search-result"><h2>Nothing in these articles is close to that.</h2><p>Parallax holds {num(data?.counts?.articles)} articles on {data?.counts?.theme_title}. Try a person, a place, a date or a number.</p><div className="empty-search-examples">{exampleData?.examples?.map(e=><button className="text-button" lang={e.lang} key={e.question} onClick={()=>navigate(`/ask?q=${encodeURIComponent(e.question)}`)}>{e.question}</button>)}</div></div>}</div>{best && <aside className="ask-explanation"><h2>How this was found</h2><p><Languages size={14} />Your question was matched by meaning, not by words, so the language does not matter.</p><p><Database size={14} />One MariaDB vector search over every stored sentence and source passage.</p><p><Check size={14} />The quotes are exact. Nothing on this page was written at query time.</p></aside>}</main><Footer />{loc.searchParams.has('sql') && <SqlDrawer queries={data?.queries} close={() => params({ sql: null })} />}</>; }

function Method() { const { data, error } = useData('method', {}), c = data?.counts, planted = data?.evaluation?.planted, fresh = data?.evaluation?.planted_fresh, third = data?.evaluation?.planted_third, blind = data?.evaluation?.blind_real; const sections = ['In the database now', 'The four checks', 'Checked, then double-checked', 'History', 'How often it is right', 'Where it fails', 'What Parallax never does']; const id = s => s.toLowerCase().replace(/[^a-z0-9]+/g, '-'); return <><main className="method-page"><nav aria-label="On this page">{sections.map(s => <a href={`#${id(s)}`} key={s}>{s}</a>)}</nav><article><h1>How Parallax checks Wikipedia</h1><p className="muted">What is stored, how each check works, how often it is right, and where it fails.</p><section id={id(sections[0])}><h2>{sections[0]}</h2><dl className="counts-table">{[['Articles', 'articles'], ['Language versions', 'versions'], ['Claims', 'claims'], ['Cited sources found', 'sources'], ['Sources read', 'sources_read'], ['Revisions stored', 'revisions'], ['Open flags', 'flags'], ['Marked not an issue by editors', 'dismissed'], ['Notes copied', 'copied']].map(([label, key]) => <div key={key}><dt>{label}</dt><dd>{c ? `${num(c[key])}${key === 'sources_read' && c.sources > 0 ? ` (${Math.round(c.sources_read / c.sources * 100)}%)` : ''}` : error ? 'unavailable' : <span className="count-skeleton" />}</dd></div>)}</dl>{c?.updated_at && <p className="small muted">Last updated {dateTime(c.updated_at)}</p>}</section><section id={id(sections[1])}><h2>{sections[1]}</h2>{Object.entries(checks).map(([kind, label]) => <div className="method-check" key={kind}><h3><Marker kind={kind} /><span className={kind}>{label}</span></h3><p>{kind === 'src' ? 'For every claim with a citation, Parallax fetches the cited page or its Internet Archive copy, stores the text in MariaDB as vectors, and retrieves the passages closest to the claim. The claim is then judged against those passages: Supported, Contradicted, Not in source. If the page cannot be read, the claim is not flagged.' : kind === 'lang' ? 'Sentences in the three versions are paired by meaning with a MariaDB vector search. A claim is flagged when one version says something the others do not, or lacks it. Missing claims are checked against the complete article. When one language has the claim with a source that supports it, Parallax suggests that version.' : kind === 'tone' ? 'Wording that praises, blames or dramatises is flagged, with a neutral wording in the same language.' : 'Dates, numbers and names are extracted from each paired claim and compared across languages and with the source.'}</p>{data?.examples?.[kind] && <Readings flag={data.examples[kind]} />}</div>)}</section><section id="distance"><h2>Language distance</h2><p>The distance is the mean cosine distance to the closest claim in each other language, using the multilingual sentence vectors. It is multiplied by 100 for the list. This is a retrieval measure, not a measurement of bias or historical truth.</p></section><section id={id(sections[2])}><h2>{sections[2]}</h2><p>Every claim is read once by a fast model, {data?.models?.[0] || 'Gemini 3.8 Flash'}. Every flag it raises is read again, separately, by a stronger model, {data?.models?.[1] || 'Gemini 4 Argon'}. The fast pass nominates candidates; the stronger pass confirms each shown flag with exact evidence. Published findings also pass an independent evidence review. The random-sample measurement below describes candidates before that additional publication filter. All of this happens before you open the page. Nothing is generated while you read.</p></section><section id={id(sections[3])}><h2>{sections[3]}</h2><p>Available revisions are loaded into MariaDB system-versioned tables. The time bar asks the database for the article as of a date. A stored boundary establishes when the marked wording appears. It does not establish when an idea first appeared, and a present-day source cannot prove what an older source said. Dates and revision lookups use UTC.</p></section><section id={id(sections[4])}><h2>{sections[4]}</h2><div className="eval-table-wrap"><table className="eval-table"><thead><tr><th>Check</th><th>Planted errors caught</th><th>False flags on clean claims</th><th>Held-out set</th></tr></thead><tbody>{Object.entries(checks).map(([kind, label]) => { const r = planted?.checks?.[kind], h = (third || fresh || planted)?.checks?.[kind]; return <tr key={kind}><th>{label}</th><td>{r ? `${r.caught} of ${r.errors}` : 'not measured'}</td><td>{h ? `${h.false_flags} of ${h.controls}` : 'not measured'}</td><td>{h ? `${h.caught} of ${h.errors}` : 'not measured'}</td></tr>; })}<tr><th>Total</th><td>{planted ? `${planted.caught} of ${planted.errors}` : 'not measured'}</td><td>{third || fresh || planted ? `${(third || fresh || planted).false_flags} of ${(third || fresh || planted).controls}` : 'not measured'}</td><td>{third || fresh || planted ? `${(third || fresh || planted).caught} of ${(third || fresh || planted).errors}` : 'not measured'}</td></tr></tbody></table></div><p className="small muted">Held-out copies of real articles test changed dates and numbers, a dropped sentence, loaded wording and unsupported claims. Prompts were frozen before the held-out run; development articles were kept separate. These are controlled passage copies, not full-article population accuracy. The first column is the original frozen run. The held-out and false-flag columns use the latest disjoint article families. The original pass caught {planted?.caught} of {planted?.errors} errors; the second caught {fresh?.caught} of {fresh?.errors}; the third caught {third?.caught} of {third?.errors}. The third uses the coverage clarification developed on Winter War copies and larger numeric changes that avoid compatible rounding. Published findings retain their recorded prompt version and independent review. These tests do not measure full multilingual clean-article false-positive rates.</p><p className="small"><A href="https://github.com/13shreyansh/parallax/blob/parallax/eval/parallax/EVALUATION.md">Read the evaluation record</A></p><h3>Blind review of real flags</h3><p>{blind ? `${blind.confirmed} of ${blind.sample_size} randomly sampled shown flags were confirmed by a separate blind review. Measured precision: ${(blind.confirmed / blind.sample_size * 100).toFixed(1)}%.` : 'Not measured yet. A separate blind review must check a random sample of 60 shown flags against the stored source texts.'}</p>{blind?.scope && <p className="small muted">{blind.scope}</p>}</section><section id={id(sections[5])}><h2>{sections[5]}</h2><ul><li>{c && c.sources > 0 ? `${Math.round((c.sources - c.sources_read) / c.sources * 100)}% of cited sources could not be read` : 'Some cited sources cannot be read'}, including books, paywalls and dead links. Those claims are not checked against their source.</li><li>A difference between languages can be fair: each version writes for readers who know different things. That is why a person decides, and why “Not an issue” exists.</li><li>Pairing sentences by meaning sometimes pairs the wrong ones. A flag can rest on a bad pair.</li><li>“Not an issue” needs no login, so anyone can dismiss or reopen a flag.</li><li>Only {c ? num(c.articles) : 'the stored'} articles in the Finland in the Second World War theme are loaded. Wikipedia may have changed since the linked revision was fetched.</li><li>Book citations with different pages are counted separately.</li><li>English glosses are machine translations. Read the original before acting.</li><li>Sources can contain tables or scans whose text is not fully extractable. Missing extracted text does not establish that a claim is absent from the original.</li></ul></section><section id={id(sections[6])}><h2>{sections[6]}</h2><p>It does not edit Wikipedia. It does not post to Talk pages. It does not decide which version is right.</p></section><A href="/a/Q134949" className="primary">See it on Winter War</A></article></main><Footer /></>; }

function App() { const loc = useLocation(), [shortcuts, setShortcuts] = useState(false); useEffect(() => { const key = e => { if (e.key === '?' && !/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) setShortcuts(s => !s); if (e.key === 'Escape') setShortcuts(false); }; window.addEventListener('keydown', key); return () => window.removeEventListener('keydown', key); }, []); return <><Header loc={loc} />{loc.pathname.startsWith('/a/') ? <Article loc={loc} key={loc.pathname} /> : loc.pathname === '/ask' ? <Ask loc={loc} /> : loc.pathname === '/method' ? <Method /> : <Home loc={loc} />}{shortcuts && <div className="shortcuts" role="region" aria-label="Keyboard shortcuts"><h2>Keyboard shortcuts</h2>{[['J / K', 'Next / previous flag'], ['C', 'Copy note for editors'], ['N', 'Not an issue'], ['[ / ]', 'Previous / next change'], ['T', 'Back to today'], ['S', 'Show the SQL'], ['/', 'Ask in any language'], ['Esc', 'Close a drawer or reading']].map(([k, v]) => <p key={k}><kbd>{k}</kbd>{v}</p>)}</div>}</>; }

createRoot(document.getElementById('root')).render(<App />);
